if (!isUuid(b.channel_id)) errors.push('channel_id must be a UUID');
if (!isUuid(b.content_project_id)) errors.push('content_project_id must be a UUID');
if (typeof b.idempotency_key !== 'string' || b.idempotency_key.length === 0 || b.idempotency_key.length > 500) errors.push('idempotency_key must be a non-empty string up to 500 characters');
if (b.correlation_id != null && !isUuid(b.correlation_id)) errors.push('correlation_id must be a UUID');
if (b.force_regenerate_chunk_ids != null && !Array.isArray(b.force_regenerate_chunk_ids)) errors.push('force_regenerate_chunk_ids must be an array');
return [{ json: {
  valid: errors.length === 0, errors,
  channel_id: b.channel_id, content_project_id: b.content_project_id,
  idempotency_key: b.idempotency_key ?? null, correlation_id: b.correlation_id ?? null,
